int simulate(char *arr, int pos, char c) {
    // make a copy to modify
    char a[MAX_N + 5];
    memcpy(a, arr, n + 1);
    a[pos] = c;

    int changed = 1;
    while (changed) {
        changed = 0;
        // find segments of 4 or more same color
        int i = 0;
        while (i < n) {
            if (a[i] == '.') { i++; continue; }
            int j = i;
            while (j < n && a[j] == a[i]) j++;
            int len = j - i;
            if (len >= 4) {
                for (int k = i; k < j; k++) a[k] = '.';
                changed = 1;
            }
            i = j;
        }
        // compress: remove '.' by shifting left
        int write = 0;
        for (int read = 0; read < n; read++) {
            if (a[read] != '.') {
                a[write++] = a[read];
            }
        }
        for (int k = write; k < n; k++) a[k] = '.';
    }
    // count remaining non-dot characters
    int cnt = 0;
    for (int i = 0; i < n; i++) if (a[i] != '.') cnt++;
    return cnt;
}

