int simulate(char *arr, int n) {
    // Stack-based simulation
    char sc[200];
    int cnt[200];
    int top = -1;

    for (int i = 0; i < n; i++) {
        char c = arr[i];
        if (top >= 0 && sc[top] == c) {
            cnt[top]++;
        } else {
            top++;
            sc[top] = c;
            cnt[top] = 1;
        }
        // Check and collapse
        while (top >= 0 && cnt[top] >= 4) {
            top--;
            // Merge top two if same color
            if (top >= 1 && sc[top] == sc[top-1]) {
                cnt[top-1] += cnt[top];
                top--;
            }
        }
    }

    int total = 0;
    for (int i = 0; i <= top; i++) total += cnt[i];
    return total;
}

