#define MAXN 205

static char s[MAXN], t[MAXN];
static int n;

/* remove all groups of length >= 4 repeatedly, return remaining length */
static int reduce_string(const char *src, int len) {
    char cur[MAXN], nxt[MAXN];
    int clen = len;
    memcpy(cur, src, len);

    while (1) {
        int i = 0, nn = 0;
        int removed = 0;

        while (i < clen) {
            int j = i + 1;
            while (j < clen && cur[j] == cur[i]) j++;
            if (j - i >= 4) {
                removed = 1;
            } else {
                for (int k = i; k < j; k++) nxt[nn++] = cur[k];
            }
            i = j;
        }

        if (!removed) return clen;
        memcpy(cur, nxt, nn);
        clen = nn;
    }
}

int main(void) {
    if (scanf("%s", s) != 1) return 0;
