    int ans = n;

    for (int pos = 0; pos < n; pos++) {
        for (int c = 0; c < 3; c++) {
            if (s[pos] == colors[c]) continue; /* must change color */

            memcpy(t, s, n);
            t[pos] = colors[c];

            int rem = reduce_string(t, n);
            if (rem < ans) ans = rem);
        }
    }

    printf("%d\n", ans);
    return 0;
}

