string collapse(string s) {
    bool changed = true;
    while (changed) {
        changed = false;
        int n = s.size();
        int i = 0;
        string ns = "";
        while (i < n) {
            int j = i;
            while (j < n && s[j] == s[i]) j++;
            if (j - i >= 4) {
                changed = true;
                // skip these
            } else {
                ns += s.substr(i, j - i);
            }
            i = j;
        }
        s = ns;
    }
    return s;
}

