static vector<pair<char,int>> compressRuns(const string& s) {
    vector<pair<char,int>> runs;
    for (char c : s) {
        if (runs.empty() || runs.back().first != c) runs.push_back({c, 1});
        else runs.back().second++;
    }
    return runs;
}

static int reducedLengthAfterElimination(vector<pair<char,int>> runs) {
    bool changed = true;
    while (changed) {
        changed = false;

        // Remove all runs with length >= 4
        vector<pair<char,int>> tmp;
        for (auto &p : runs) {
            if (p.second < 4) tmp.push_back(p);
            else changed = true;
        }
        runs.swap(tmp);

        // Merge adjacent same-color runs created after removals
        vector<pair<char,int>> merged;
        for (auto &p : runs) {
            if (!merged.empty() && merged.back().first == p.first) {
                merged.back().second += p.second;
                changed = true;
            } else {
                merged.push_back(p);
            }
        }
        runs.swap(merged);
    }

    int total = 0;
    for (auto &p : runs) total += p.second;
    return total;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

