    for (int i = 0; i < N; ++i) {
        for (char c : colors) {
            if (c == s[i]) continue;
            string t = s;
            t[i] = c;

            auto runs = compressRuns(t);
            answer = min(answer, reducedLengthAfterElimination(runs));
        }
    }

