        for (int i = 0; i < n; i++) {
            char original = arr[i];
            for (char col : new char[]{'R', 'B', 'Y'}) {
                if (col == original) continue;
                arr[i] = col;
                minRemaining = Math.min(minRemaining, simulate(arr));
                arr[i] = original;
            }
        }

        System.out.println(minRemaining);
    }

    // Simulate the elimination process on a copy of the array
    static int simulate(char[] arr) {
        // Use a mutable list to simulate removals
        List<Character> list = new ArrayList<>();
        for (char c : arr) list.add(c);

        boolean changed = true;
        while (changed) {
            changed = false;
            // Scan for runs of 4 or more
            int start = 0;
            for (int i = 1; i <= list.size(); i++) {
                if (i == list.size() || list.get(i) != list.get(start)) {
                    if (i - start >= 4) {
                        // Remove from start to i-1
                        for (int j = i - 1; j >= start; j--) {
                            list.remove(j);
                        }
                        changed = true;
                        break; // restart scan after removal
                    }
                    start = i;
                }
            }
        }
        return list.size();
    }
}

