public class Main {
    static int N;
    static char[] s;
    static int best;

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static int simulate(char[] arr) {
        ArrayList<Character> list = new ArrayList<>();
        for (char c : arr) list.add(c);

        boolean changed = true;
        while (changed) {
            changed = false;
            ArrayList<Character> next = new ArrayList<>();
            int i = 0;
            while (i < list.size()) {
                int j = i + 1;
                while (j < list.size() && list.get(j) == list.get(i)) j++;
                int len = j - i;
                if (len < 4) {
                    for (int k = i; k < j; k++) next.add(list.get(k));
                } else {
                    changed = true;
                }
                i = j;
            }
            list = next;
        }
        return list.size();
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        N = fs.nextInt();
        String str = fs.next();
        s = str.toCharArray();

        char[] colors = {'R', 'B', 'Y'};
        best = N;

        for (int i = 0; i < N; i++) {
            char original = s[i];
            for (char c : colors) {
                if (c == original) continue;
                char[] t = s.clone();
                t[i] = c;
                best = Math.min(best, simulate(t));
            }
        }

        System.out.println(best);
    }
}

def simulate(s):
    # Repeatedly remove 4+ consecutive same colors until stable
    while True:
        new_s = []
        i = 0
        n = len(s)
        removed = False
        while i < n:
            j = i
            while j < n and s[j] == s[i]:
                j += 1
            if j - i >= 4:
                removed = True
                # skip these characters
                i = j
                continue
            new_s.extend(s[i:j])
            i = j
        if not removed:
            break
        s = new_s
    return len(s)

