import sys
from functools import lru_cache

def solve():
    input = sys.stdin.readline
    N = int(input().strip())
    s = input().strip()

    # Run-length encode
    colors = []
    counts = []
    for ch in s:
        if colors and colors[-1] == ch:
            counts[-1] += 1
        else:
            colors.append(ch)
            counts.append(1)

    m = len(colors)

    @lru_cache(maxsize=None)
    def remain(l, r, lc, ln, rc, rn):
        """
        Remaining number of balls in runs [l..r] after all possible eliminations,
        assuming there is an extra run (lc, ln) immediately to the left and
        an extra run (rc, rn) immediately to the right.
        lc/rc are 0..2 for colors, 3 means no run.
        ln/rn are lengths (0 if no run).
        """
        if l > r:
            if lc != 3 and rc != 3 and lc == rc and ln + rn >= 4:
                return 0
            return (ln if lc != 3 else 0) + (rn if rc != 3 else 0)

        left_c = colors[l]
        left_n = counts[l]

        # Merge left boundary run with current left run if same color
        if lc != 3 and lc == left_c:
            new_lc = lc
            new_ln = ln + left_n
        else:
            new_lc = left_c
            new_ln = left_n
            if lc != 3 and ln >= 4:
                return remain(l, r, 3, 0, rc, rn)

        # If merged left run disappears, recurse inward
        if new_ln >= 4:
            return remain(l + 1, r, 3, 0, rc, rn)

        # Symmetric processing from right side
        right_c = colors[r]
        right_n = counts[r]

        if rc != 3 and rc == right_c:
            new_rc = rc
            new_rn = rn + right_n
        else:
            new_rc = right_c
            new_rn = right_n
            if rc != 3 and rn >= 4:
                return remain(l, r, lc, ln, 3, 0)

        if new_rn >= 4:
            return remain(l, r - 1, lc, ln, 3, 0)

        if l == r:
            total = 0
            if new_lc == new_rc:
                if new_ln + new_rn >= 4:
                    total = 0
                else:
                    total = new_ln + new_rn
            else:
                total = new_ln + new_rn
            return total

        # No immediate boundary elimination possible; count middle runs plus boundaries
        total = new_ln + new_rn
        for i in range(l + 1, r):
            total += counts[i]
        return total

    color_id = {'R': 0, 'B': 1, 'Y': 2}
    rev = ['R', 'B', 'Y']

    ans = N

    # Try changing each position to each other color
    for i, ch in enumerate(s):
        for nc in rev:
            if nc == ch:
                continue

            # Build modified string locally via neighboring runs logic
            # Find run containing i
            pos = 0
            run_idx = 0
            while pos + counts[run_idx] <= i:
                pos += counts[run_idx]
                run_idx += 1

            offset = i - pos
            c = colors[run_idx]
            k = counts[run_idx]

            left_parts = []
            if offset > 0:
                left_parts.append((c, offset))
            mid = (nc, 1)
            if offset + 1 < k:
                left_parts.append((c, k - offset - 1))

            runs2 = []
            for j in range(run_idx):
                runs2.append((colors[j], counts[j]))
            for p in left_parts[:1]:
                runs2.append(p)
            runs2.append(mid)
            for p in left_parts[1:]:
                runs2.append(p)
            for j in range(run_idx + 1, m):
                runs2.append((colors[j], counts[j]))

            # Merge adjacent equal colors
            merged = []
            for cc, nn in runs2:
                if nn == 0:
                    continue
                if merged and merged[-1][0] == cc:
                    merged[-1] = (cc, merged[-1][1] + nn)
                else:
                    merged.append((cc, nn))

            # Evaluate elimination on this modified run list
            old_colors, old_counts = colors, counts
            colors = [x[0] for x in merged]
            counts = [x[1] for x in merged]
            mm = len(colors)

            remain.cache_clear()
            cur = remain(0, mm - 1, 3, 0, 3, 0)
            ans = min(ans, cur)

            colors, counts = old_colors, old_counts

    print(ans)

